(function(){
  function closeDropdowns(except){document.querySelectorAll('.dropdown.is-open').forEach(function(d){if(d!==except){d.classList.remove('is-open');var b=d.querySelector('button');if(b)b.setAttribute('aria-expanded','false')}})}
  function addReadingProgress(){if(document.querySelector('.reading-progress'))return;var p=document.createElement('div');p.className='reading-progress';p.setAttribute('aria-hidden','true');p.innerHTML='<span></span>';document.body.appendChild(p);var b=p.firstElementChild;function u(){var m=document.documentElement.scrollHeight-window.innerHeight,v=m>0?Math.min(100,Math.max(0,window.scrollY/m*100)):0;b.style.transform='scaleX('+(v/100)+')'}u();window.addEventListener('scroll',u,{passive:true});window.addEventListener('resize',u,{passive:true})}
  function enhanceTables(){var c=document.querySelector('.article-content');if(!c)return;c.querySelectorAll('table').forEach(function(t){if(t.parentElement&&t.parentElement.classList.contains('table-scroll'))return;var w=document.createElement('div');w.className='table-scroll';w.setAttribute('tabindex','0');w.setAttribute('role','region');w.setAttribute('aria-label','Bảng nội dung, có thể cuộn ngang');t.parentNode.insertBefore(w,t);w.appendChild(t)})}
  document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.dropdown > button').forEach(function(b){b.type='button';b.setAttribute('aria-haspopup','true');b.setAttribute('aria-expanded','false');b.addEventListener('click',function(e){var d=b.closest('.dropdown');if(!d)return;var h=window.matchMedia('(hover: hover) and (pointer: fine)').matches;if(!h){e.preventDefault();e.stopPropagation();var o=!d.classList.contains('is-open');closeDropdowns(d);d.classList.toggle('is-open',o);b.setAttribute('aria-expanded',o?'true':'false')}})});document.addEventListener('click',function(e){if(!e.target.closest('.dropdown'))closeDropdowns()});document.addEventListener('keydown',function(e){if(e.key==='Escape')closeDropdowns()});enhanceTables();addReadingProgress()})
})();
